Model Wizard > Metal Processing > Induction Hardening
Magnetic Fields: coil current 1 kA at 50 kHz during heating, switched off for quenching
// Application Library: Metal_Processing_Module/Induction_Hardening/induction_hardening_of_a_cylindrical_pin

model.thermodynamics().feature().create("pp1", "BuiltinPropertyPackage");
model.thermodynamics().feature("pp1").set("phase_list", new String[][]{{"Vapor", "Vapor"}, {"Liquid", "Liquid"}});
model.thermodynamics().feature("pp1").set("ThermodynamicModel", "UNIFAC");
model.thermodynamics().feature("pp1").set("LiquidPhaseModel", "UNIFAC");
model.thermodynamics().feature("pp1").set("GasPhaseModel", "IdealGas");
model.thermodynamics().feature("pp1").set("VapViscosity", "Brokaw");
// Application Library: Liquid_and_Gas_Properties_Module/Tutorials/engine_coolant_properties; Peng-Robinson gas: carbon_dioxide_storage

Thermodynamics > Thermodynamic System: Vapor-liquid, species water, model Water (IAPWS)
Species Property: Heat of vaporization, Vapor pressure, Density (Liquid, Vapor)
// Application Library: Chemical_Reaction_Engineering_Module/Thermodynamics/heat_pipe (Water model in Java)

model.thermodynamics().feature("pp1").feature().create("singlephase1", "OnePhaseProperty");
model.thermodynamics().feature("pp1").feature("singlephase1").set("property", "Density");
model.thermodynamics().feature("pp1").feature("singlephase1").set("phase", "Liquid");
model.thermodynamics().feature("pp1").feature("singlephase1").set("comp_basis", "mass");
model.thermodynamics().feature("pp1").feature().create("flashcalc1", "FlashCalculationProperty");
model.thermodynamics().feature("pp1").feature("flashcalc1").set("phases", new String[]{"Vapor", "Liquid"});
// Application Library: Liquid_and_Gas_Properties_Module/Tutorials/engine_coolant_properties, phase_envelope, heat_pipe

model.component("comp1").material("mat1").propertyGroup("def").func("k").set("arg", "T");
model.component("comp1").material("mat1").propertyGroup("def").func("k").set("argunit", "K");
model.component("comp1").material("mat1").propertyGroup("def").func("k").set("fununit", "W/(m*K)");
// explicit use in an expression: mat1.def.k(T)

model.component("comp1").material("mat1").propertyGroup().create("JohnsonCook", "JohnsonCook", "Johnson-Cook");
model.component("comp1").material("mat1").propertyGroup("JohnsonCook").set("k_jcook", "510[MPa]");
model.component("comp1").material("mat1").propertyGroup("JohnsonCook").set("n_jcook", "0.26");
// Metal Processing: per-phase hardening in Metallurgical Phase nodes uses these groups

